import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import menuItemService from '../../services/menuItemService';
import { useAuth } from '../../hooks/useAuth';

const EditMenuItem = () => {
  const { id } = useParams();
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [price, setPrice] = useState('');
  const [category, setCategory] = useState('');
  const [isAvailable, setIsAvailable] = useState(true);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const { token } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    const fetchMenuItem = async () => {
      setLoading(true);
      setError('');
      try {
        const items = await menuItemService.getMenuItemsByOwner(token);
        const menuItemToEdit = items.find(i => i._id === id);
        if (menuItemToEdit) {
          setName(menuItemToEdit.name);
          setDescription(menuItemToEdit.description || '');
          setPrice(menuItemToEdit.price);
          setCategory(menuItemToEdit.category || '');
          setIsAvailable(menuItemToEdit.isAvailable);
        } else {
          setError('Menu item not found or unauthorized.');
          navigate('/restaurant/dashboard');
        }
      } catch (err) {
        setError(err.message || 'Failed to fetch menu item details.');
      } finally {
        setLoading(false);
      }
    };

    fetchMenuItem();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [token, id, navigate]);

  const handleSubmit = async (event) => {
    event.preventDefault();
    setSaving(true);
    setError('');
    try {
      const updatedMenuItem = {
        name,
        description,
        price: parseFloat(price),
        category,
        isAvailable,
      };
      await menuItemService.updateMenuItem(id, updatedMenuItem, token);
      console.log('Menu item updated successfully.');
      setSaving(false);
      navigate('/restaurant/dashboard');
    } catch (err) {
      setError(err.message || 'Failed to update menu item.');
      setSaving(false);
    }
  };

  if (loading) {
    return <div>Loading menu item details...</div>;
  }

  if (error) {
    return <div style={{ color: 'red' }}>{error}</div>;
  }

  return (
    <div>
      <h2>Edit Menu Item</h2>
      {error && <p style={{ color: 'red' }}>{error}</p>}
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="name">Name:</label>
          <input type="text" id="name" value={name} onChange={(e) => setName(e.target.value)} required />
        </div>
        <div>
          <label htmlFor="description">Description:</label>
          <textarea id="description" value={description} onChange={(e) => setDescription(e.target.value)} />
        </div>
        <div>
          <label htmlFor="price">Price:</label>
          <input type="number" id="price" value={price} onChange={(e) => setPrice(e.target.value)} required />
        </div>
        <div>
          <label htmlFor="category">Category:</label>
          <input type="text" id="category" value={category} onChange={(e) => setCategory(e.target.value)} />
        </div>
        <div>
          <label htmlFor="isAvailable">Available:</label>
          <input
            type="checkbox"
            id="isAvailable"
            checked={isAvailable}
            onChange={(e) => setIsAvailable(e.target.checked)}
          />
        </div>
        <button type="submit" disabled={saving}>
          {saving ? 'Saving...' : 'Save Menu Item'}
        </button>
      </form>
    </div>
  );
};

export default EditMenuItem;
